export const membershipPlans={annual:{name:'7-Day Full Access',price:39.99,period:'year',detail:'Then $39.99/year',displayPrice:'$0.00',displayPeriod:'week'},monthly:{name:'Monthly',price:5.99,period:'month',detail:'$5.99 billed monthly',displayPrice:'$1.38',displayPeriod:'week*'}};
export function membershipOffer(id){return id==='annual'?{cta:'Try for $0.00',payment:'✓ No payment due now',disclaimer:'7 days free, then $39.99/year. Your Apple Account will be charged when the trial ends. Renews automatically unless canceled at least 24 hours before the trial or subscription period ends. Free trial for eligible new subscribers only. Manage or cancel in Apple Settings. Prices in USD.',confirmation:'7 days free, then $39.99 per year. No payment due now.'}:{cta:'Continue for $5.99',payment:'$5.99 due today',disclaimer:'$5.99/month, charged to your Apple Account at confirmation. No free trial. Renews automatically at $5.99/month unless canceled at least 24 hours before the current period ends. Manage or cancel in Apple Settings. Prices in USD. *About $1.38/week; billed monthly, not weekly.',confirmation:'$5.99 due today, then $5.99 per month. No free trial.'}};

let selected='annual',dialog,previousFocus;
const closeIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg>';
function render(){const offer=membershipOffer(selected);dialog.innerHTML=`<div class="membership-paywall"><header class="membership-top"><span>Bible Scroll Plus</span><button data-member="close" aria-label="Close membership preview">${closeIcon}</button></header><div class="membership-scroll"><div class="membership-art" aria-hidden="true"><img class="membership-clouds" src="illustration-pack/cloud-bank.png" alt="" width="480" height="208"><img class="membership-book" src="illustration-pack/open-book.png" alt="" width="158" height="140"><img class="membership-flower" src="illustration-pack/cosmos.png" alt="" width="78" height="86"></div><h2 id="membership-title">A little deeper.<br><em>A little closer.</em></h2><p class="membership-sub">Make room for your faith,<br>in the middle of your real life.</p><ul class="membership-features"><li><img src="illustration-pack/seedling.png" alt="" width="28" height="32">Guided reading at your pace</li><li><img src="illustration-pack/lantern.png" alt="" width="28" height="32">Passage study & thoughtful reflections</li><li><img src="illustration-pack/bookmark.png" alt="" width="28" height="32">Keep meaningful verses close</li></ul><p class="membership-payment-note" aria-live="polite">${offer.payment}</p><fieldset class="membership-plans"><legend>Choose your plan</legend>${Object.entries(membershipPlans).map(([id,p])=>`<label class="membership-plan ${selected===id?'chosen':''}"><input type="radio" name="membership-plan" value="${id}" ${selected===id?'checked':''}><span class="plan-choice-indicator"></span><span class="membership-plan-copy"><strong>${p.name}${id==='annual'?'<b>7 days free</b>':''}</strong><small>${p.detail}</small></span><span class="membership-amount">${p.displayPrice}<small>/${p.displayPeriod}</small></span></label>`).join('')}</fieldset></div><footer class="membership-footer"><p class="membership-renewal" aria-live="polite">${offer.disclaimer}</p><button class="membership-cta" data-member="preview">${offer.cta}</button><button class="membership-free" data-member="close">Continue with free reading</button><p class="membership-demo">Demo only · No payment will be taken.</p><div class="membership-links"><button data-member="restore">Restore purchases</button><button data-member="terms">Terms</button><button data-member="privacy">Privacy</button></div><p class="membership-notice" role="status" aria-live="polite"></p></footer></div>`;}
export function showMembership(){if(!dialog){dialog=document.createElement('dialog');dialog.id='membership-dialog';dialog.setAttribute('aria-labelledby','membership-title');document.body.append(dialog);dialog.addEventListener('change',e=>{if(e.target.name==='membership-plan'){selected=e.target.value==='monthly'?'monthly':'annual';render();dialog.querySelector('input:checked')?.focus()}});dialog.addEventListener('close',()=>previousFocus?.isConnected&&previousFocus.focus({preventScroll:true}));dialog.addEventListener('click',e=>{const action=e.target.closest('[data-member]')?.dataset.member;if(!action)return;if(action==='close'){dialog.close();return}if(action==='preview'){const p=membershipPlans[selected];dialog.innerHTML=`<div class="membership-confirm"><img src="illustration-pack/butterfly.png" alt="" width="110" height="90"><h2 id="membership-title">Your ${p.name.toLowerCase()} plan preview</h2><p>${membershipOffer(selected).confirmation}</p><p>This is a design demo. No purchase was made and no payment details were collected.</p><button class="membership-cta" data-member="close">Return to the app</button><button class="membership-free" data-member="plans">Back to plans</button></div>`;dialog.querySelector('button').focus();return}if(action==='plans'){render();return}const messages={restore:'No App Store connection in this demo. Restore purchases will be available in the native app.',terms:'Preview terms: the selected plan renews at its displayed rate until canceled. Live purchases would be managed in your Apple account settings. No agreement or charge is created here.',privacy:'This paywall preview collects no payment information and sends no purchase data. App preferences remain in this browser.'};dialog.querySelector('.membership-notice').textContent=messages[action]||'';});}previousFocus=document.activeElement;render();if(!dialog.open)dialog.showModal();dialog.querySelector('[data-member="close"]').focus();}
window.addEventListener('bible-paywall-preview',showMembership);
